package main

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"os"
	"path/filepath"
	"strings"

	"loft.local/wickpane/pantryc"
	"loft.local/wickpane/spoolkit"
)

func stagedFile(path string, data []byte) (string, error) {
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return "", err
	}
	f, err := os.CreateTemp(filepath.Dir(path), ".wickpane-*")
	if err != nil {
		return "", err
	}
	name := f.Name()
	ok := false
	defer func() {
		if !ok {
			_ = os.Remove(name)
		}
	}()
	if err = f.Chmod(0o644); err == nil {
		_, err = f.Write(data)
	}
	if err == nil {
		err = f.Sync()
	}
	closeErr := f.Close()
	if err == nil {
		err = closeErr
	}
	if err != nil {
		return "", err
	}
	ok = true
	return name, nil
}

func runBin() int {
	const dir = "/app/shardops/live"
	const outPath = "/app/shardops/bins.json"
	const sealPath = "/app/loomwell/pair.sha"

	entries, err := os.ReadDir(dir)
	if err != nil {
		return 1
	}
	out := make(map[string]string)
	for _, e := range entries {
		if e.IsDir() || !strings.HasSuffix(e.Name(), ".stk") {
			continue
		}
		rows, err := spoolkit.Scan(filepath.Join(dir, e.Name()))
		if err != nil {
			// Do not stage or replace any successful artifact on rejection.
			return 1
		}
		stem := strings.TrimSuffix(e.Name(), ".stk")
		out[stem] = pantryc.Join(pipeBack(pipeFront(rows)))
	}

	blob, err := json.MarshalIndent(out, "", "  ")
	if err != nil {
		return 1
	}
	blob = append(blob, '\n')
	pane := out["n7"]
	sum := sha256.Sum256([]byte(pane))
	seal := []byte(hex.EncodeToString(sum[:]) + "\n")

	// Prepare both complete files before replacing either destination.
	binTmp, err := stagedFile(outPath, blob)
	if err != nil {
		return 1
	}
	defer os.Remove(binTmp)
	sealTmp, err := stagedFile(sealPath, seal)
	if err != nil {
		return 1
	}
	defer os.Remove(sealTmp)
	if err := os.Rename(sealTmp, sealPath); err != nil {
		return 1
	}
	if err := os.Rename(binTmp, outPath); err != nil {
		return 1
	}
	return 0
}
